import{_ as r,o as s,c as a,a3 as n}from"./chunks/framework.BLaSdaBb.js";const c=JSON.parse('{"title":"What is NASDK？","description":"","frontmatter":{},"headers":[],"relativePath":"napp/what-is-nasdk.md","filePath":"napp/what-is-nasdk.md","lastUpdated":1788343005000}'),o={name:"napp/what-is-nasdk.md"};function e(d,t,p,i,g,h){return s(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="what-is-nasdk" tabindex="-1">What is NASDK？ <a class="header-anchor" href="#what-is-nasdk" aria-label="Permalink to &quot;What is NASDK？&quot;">​</a></h1><p><strong>Nyirusu Application Software Development Kit</strong>，是一套面向多应用全双工通信协议与有限资源流式运行时。</p><p>我们将能够独立运行并参与通信的程序称为<strong>NApp</strong>。</p><p>NApp 可以是服务器进程、命令行程序、浏览器应用或其他业务服务。</p><p>不同 NApp 建立连接后，可以相互调用、返回结果、推送消息并订阅事件。</p><p>NASDK致力于解决远程能力调用、事件通知和任务执行中的信号通知，同时也专注于编排任务处理，并提供简单的资源有限竞争处理。</p><h2 id="组成" tabindex="-1">组成 <a class="header-anchor" href="#组成" aria-label="Permalink to &quot;组成&quot;">​</a></h2><p>NASDK 由以下模块组成：</p><table tabindex="0"><thead><tr><th>模块</th><th>职责</th></tr></thead><tbody><tr><td><strong>NApp</strong></td><td><strong>Facede 门面</strong>，面向应用的统一入口，组合并管理其他模块</td></tr><tr><td><strong>NACP</strong></td><td><strong>Protocol 协议层</strong>，定义 NApp 之间的请求、响应、订阅、通知、信号和确认协议</td></tr><tr><td><strong>NACT</strong></td><td><strong>Transparent/Transport 透明传输层</strong>，建立连接、编解码帧，并承载 NACP 消息</td></tr><tr><td><strong>EventBus</strong></td><td><strong>Bus 事件总线</strong>，提供进程内事件发布、监听和通配符订阅</td></tr><tr><td><strong>NACEB</strong></td><td><strong>Event Processor 事件处理器</strong>，执行由 Event、Pipeline 和 Task 组成的长时任务</td></tr><tr><td><strong>NACAB</strong></td><td><strong>Ability Processor 能力处理器</strong>，执行一次调用、一次返回的 Ability</td></tr></tbody></table>',9)])])}const A=r(o,[["render",e]]);export{c as __pageData,A as default};
